function save_data(string $file, array $data): void { file_put_contents($file, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES), LOCK_EX); }
function token(): string { return $_SESSION['token'] ??= bin2hex(random_bytes(24)); }
function old_value(string $key, mixed $fallback = ''): string { return htmlspecialchars((string) ($_SESSION['old'][$key] ?? $fallback), ENT_QUOTES, 'UTF-8'); }
function redirect_back_with_errors(array $errors, string $url): never { $_SESSION['errors'] = $errors; $_SESSION['old'] = $_POST; header('Location: ' . $url); exit; }
function verify_post(): void { if (!hash_equals($_SESSION['token'] ?? '', $_POST['_token'] ?? '')) { http_response_code(419); exit('Page expired. Refresh and try again.'); } }
function record_by_id(array $rows, int $id): ?array { foreach ($rows as $row) if ((int) $row['id'] === $id) return $row; return null; }
function upload_avatar(?array $file): string {
    if (!$file || ($file['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) return '';
    if (($file['size'] ?? 0) > 2097152) return 'Avatar must not be larger than 2 MB.';
    $info = @getimagesize($file['tmp_name']);
    if (!$info || !in_array($info['mime'], ['image/jpeg', 'image/png', 'image/gif', 'image/webp'], true)) return 'Avatar must be a JPG, PNG, GIF, or WEBP image.';
    if (!extension_loaded('gd')) return 'GD is required on the hosting account.';
    $source = @imagecreatefromstring(file_get_contents($file['tmp_name']));
    if (!$source) return 'The selected image could not be read.';
    $side = min(imagesx($source), imagesy($source)); $target = imagecreatetruecolor(300, 300);
    imagecopyresampled($target, $source, 0, 0, (imagesx($source) - $side) / 2, (imagesy($source) - $side) / 2, 300, 300, $side, $side);
    if (!is_dir(__DIR__ . '/uploads')) mkdir(__DIR__ . '/uploads', 0755, true);
    $name = bin2hex(random_bytes(16)) . '.jpg'; imagejpeg($target, __DIR__ . '/uploads/' . $name, 88);
    imagedestroy($source); imagedestroy($target); return $name;
}
function avatar_url(?string $name, string $fullName): string { global $root; if ($name && is_file(__DIR__ . '/uploads/' . $name)) return $root('/uploads/' . $name); return 'data:image/svg+xml,' . rawurlencode('<svg xmlns="http://www.w3.org/2000/svg" width="60" height="60"><rect width="100%" height="100%" fill="#e8eef7"/><text x="50%" y="58%" text-anchor="middle" fill="#12304a" font-size="25">' . strtoupper(substr($fullName, 0, 1)) . '</text></svg>'); }
function error_text(string $key): string { $errors = $_SESSION['errors'] ?? []; return isset($errors[$key]) ? '<div class="error">' . htmlspecialchars($errors[$key], ENT_QUOTES, 'UTF-8') . '</div>' : ''; }
