    if ($path === '/customers' && $method === 'GET') { $body = '<h1>Customer Accounts</h1><p class="lead">TFA6 records with TFA7 create and edit workflows.</p><p><a class="button" href="' . $root('/customers/create') . '">+ Create Customer</a></p><div class="table-wrap"><table><tr><th>ID</th><th>Full Name</th><th>Email</th><th>Phone</th><th>Action</th></tr>'; foreach ($data['customers'] as $row) $body .= '<tr><td>' . $esc($row['id']) . '</td><td>' . $esc($row['full_name']) . '</td><td>' . $esc($row['email']) . '</td><td>' . $esc($row['phone']) . '</td><td><a href="' . $root('/customers/' . $row['id'] . '/edit') . '">Edit</a></td></tr>'; render_page('Customer Accounts', $body . '</table></div>'); exit; }
