    if (($path === '/customers/create' || preg_match('#^/customers/\d+/edit$#', $path)) && $method === 'GET') { $edit = preg_match('#^/customers/(\d+)/edit$#', $path, $match); $row = $edit ? record_by_id($data['customers'], (int)$match[1]) : null; if ($edit && !$row) exit('Customer not found'); $action = $edit ? '/customers/' . $row['id'] . '/update' : '/customers'; $body = '<h1>' . ($edit ? 'Edit' : 'Create') . ' Customer</h1><div class="card"><form method="post" action="' . $root($action) . '"><input type="hidden" name="_token" value="' . $esc(token()) . '"><label>Full name</label><input name="full_name" value="' . old_value('full_name', $row['full_name'] ?? '') . '">' . error_text('full_name') . '<label>Email</label><input type="email" name="email" value="' . old_value('email', $row['email'] ?? '') . '">' . error_text('email') . '<label>Phone</label><input name="phone" value="' . old_value('phone', $row['phone'] ?? '') . '">' . error_text('phone') . '<label>Address</label><input name="address" value="' . old_value('address', $row['address'] ?? '') . '">' . error_text('address') . '<p><button class="button" type="submit">' . ($edit ? 'Update' : 'Save') . ' Customer</button> <a href="' . $root('/customers') . '">Cancel</a></p></form></div>'; render_page('Customer Form', $body); exit; }
    if (($path === '/users/create' || preg_match('#^/users/\d+/edit$#', $path)) && $method === 'GET') { $edit = preg_match('#^/users/(\d+)/edit$#', $path, $match); $row = $edit ? record_by_id($data['users'], (int)$match[1]) : null; if ($edit && !$row) exit('User not found'); $action = $edit ? '/users/' . $row['id'] . '/update' : '/users'; $body = '<h1>' . ($edit ? 'Edit' : 'Create') . ' User</h1><div class="card"><form method="post" enctype="multipart/form-data" action="' . $root($action) . '"><input type="hidden" name="_token" value="' . $esc(token()) . '"><label>Username</label><input name="username" value="' . old_value('username', $row['username'] ?? '') . '">' . error_text('username') . '<label>Full name</label><input name="full_name" value="' . old_value('full_name', $row['full_name'] ?? '') . '">' . error_text('full_name') . '<label>Email</label><input type="email" name="email" value="' . old_value('email', $row['email'] ?? '') . '">' . error_text('email'); if ($edit) $body .= '<label>Profile picture</label><input type="file" name="avatar" accept="image/jpeg,image/png,image/gif,image/webp"><small>Image only, maximum 2 MB.</small>' . error_text('avatar'); $body .= '<p><button class="button" type="submit">' . ($edit ? 'Update' : 'Save') . ' User</button> <a href="' . $root('/users') . '">Cancel</a></p></form></div>'; render_page('User Form', $body); exit; }
    if ($method === 'POST' && ($path === '/customers' || preg_match('#^/customers/\d+/update$#', $path))) { $edit = preg_match('#^/customers/(\d+)/update$#', $path, $match); $v = ['full_name'=>trim($_POST['full_name']??''),'email'=>trim($_POST['email']??''),'phone'=>trim($_POST['phone']??''),'address'=>trim($_POST['address']??'')]; $e=[]; if ($v['full_name']==='') $e['full_name']='This field is required.'; if (!filter_var($v['email'],FILTER_VALIDATE_EMAIL)) $e['email']='Enter a valid email address.'; if($e) redirect_back_with_errors($e,$root($edit?'/customers/'.$match[1].'/edit':'/customers/create')); if($edit) foreach($data['customers'] as &$row) if((int)$row['id']===(int)$match[1]) $row=array_merge($row,$v); else { $v['id']=count($data['customers'])?max(array_column($data['customers'],'id'))+1:1; $data['customers'][]=$v; } save_data($dataFile,$data); $_SESSION['flash']='Customer ' . ($edit?'updated':'created') . ' successfully.'; header('Location: '.$root('/customers')); exit; }
